    "AnalyzeResultChecks": {
      "properties": {
        "reward_hacking": {
          "$ref": "#/$defs/QualityCheckModel"
        },
        "task_specification": {
          "$ref": "#/$defs/QualityCheckModel"
        }
      },
      "required": [
        "reward_hacking",
