import json
d = json.load(open('agent/trajectory.json'))
steps = d['steps']
for i, s in enumerate(steps):
    role = s.get('role') or s.get('type')
    content = s.get('content')
    text = ''
    if isinstance(content, list):
        parts = []
        for c in content:
            if isinstance(c, dict):
                if c.get('type') == 'text':
                    parts.append(c.get('text','')[:200])
                elif c.get('type') == 'tool_use':
                    parts.append(f\"TOOL_USE:{c.get('name')} {json.dumps(c.get('input'))[:200]}\")
                elif c.get('type') == 'tool_result':
                    cc = c.get('content')
                    if isinstance(cc, list):
                        for x in cc:
                            if isinstance(x, dict) and x.get('type')=='text':
                                parts.append('TOOL_RESULT:' + x.get('text','')[:200])
                    else:
                        parts.append('TOOL_RESULT:' + str(cc)[:200])
        text = ' | '.join(parts)
    elif isinstance(content, str):
        text = content[:300]
    print(i, role, text[:400])
    print('---')
"

